import graphene
from graphene_django import DjangoObjectType
from .models import Book, Author


class AuthorType(DjangoObjectType):
    class Meta:
        model = Author
        fields = ("id", "full_name", "bio")


class BookType(DjangoObjectType):
    class Meta:
        model = Book
        fields = ("id", "title", "author", "price", "published_at")


class Query(graphene.ObjectType):
    books = graphene.List(BookType, category=graphene.String())
    book = graphene.Field(BookType, id=graphene.Int(required=True))

    def resolve_books(self, info, category=None):
        qs = Book.objects.select_related("author")
        if category:
            qs = qs.filter(category__slug=category)
        return qs

    def resolve_book(self, info, id):
        return Book.objects.select_related("author").get(pk=id)


schema = graphene.Schema(query=Query)

class GraphQLView(JWTGraphQLView):
    @classmethod
    def as_view(cls, *args, **kwargs):
        view = super().as_view(*args, **kwargs)
        return csrf_exempt(view)


class Query(graphene.ObjectType):
    me = graphene.Field(UserType)

    def resolve_me(self, info):
        user = info.context.user
        if not user.is_authenticated:
            raise Exception("Not authenticated")
        return user


class CreateBook(graphene.Mutation):
    class Arguments:
        title = graphene.String(required=True)
        price = graphene.Decimal(required=True)

    book = graphene.Field(BookType)

    def mutate(self, info, title, price):
        user = info.context.user
        if not user.is_authenticated:
            raise Exception("Not authenticated")
        book = Book.objects.create(title=title, price=price, owner=user)
        return CreateBook(book=book)

